import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { Line } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend } from 'chart.js';
import PasswordChangeModal from './PasswordChangeModal';
import styles from './ProfilePage.module.css';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

const ProfilePage = () => {
    const [userData, setUserData] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [editedData, setEditedData] = useState({});
    const [isPasswordModalOpen, setIsPasswordModalOpen] = useState(false);
    const [validationErrors, setValidationErrors] = useState({});

    const { userId } = useParams();
    const navigate = useNavigate();
    const { axiosAuth, logout } = useAuth();

    useEffect(() => {
        fetchUserData();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [userId]);

    const fetchUserData = async () => {
        try {
            setLoading(true);
            const response = await axiosAuth.get(`/users/profile/${userId}`);
            setUserData(response.data);
            setEditedData({
                name: response.data.name,
                surname: response.data.surname,
                email: response.data.email,
                username: response.data.username
            });
            setError(null);
        } catch (err) {
            console.error('Error fetching user data:', err);
            setError('Failed to load user data. Please try again.');
            if (err.response && err.response.status === 403) {
                logout();
                navigate('/login');
            }
        } finally {
            setLoading(false);
        }
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setEditedData(prev => ({ ...prev, [name]: value }));
        setValidationErrors(prev => ({ ...prev, [name]: '' }));
    };

    const validateForm = () => {
        const errors = {};
        if (editedData.email && !/\S+@\S+\.\S+/.test(editedData.email)) {
            errors.email = 'Invalid email format';
        }
        setValidationErrors(errors);
        return Object.keys(errors).length === 0;
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!validateForm()) return;

        try {
            await axiosAuth.put(`/users/profile/${userId}`, editedData);
            fetchUserData();
            alert('Profile updated successfully');
        } catch (err) {
            console.error('Error updating profile:', err);
            if (err.response && err.response.data.message) {
                setValidationErrors({ email: err.response.data.message });
            } else {
                setError('Failed to update profile. Please try again.');
            }
        }
    };

    if (loading) {
        return (
            <div className={styles.loaderContainer}>
                <div className={styles.loader}></div>
            </div>
        );
    }
    if (error) return <div className={styles.error}>{error}</div>;
    if (!userData) return null;

    const chartData = {
        labels: userData.gameHistory && userData.gameHistory.length > 0 
            ? userData.gameHistory.map(game => game.date)
            : ['No data'],
        datasets: [
            {
                label: 'Wins',
                data: userData.gameHistory && userData.gameHistory.length > 0 
                    ? userData.gameHistory.map(game => game.wins)
                    : [0],
                borderColor: 'rgb(75, 192, 192)',
                tension: 0.1
            },
            {
                label: 'Losses',
                data: userData.gameHistory && userData.gameHistory.length > 0 
                    ? userData.gameHistory.map(game => game.losses)
                    : [0],
                borderColor: 'rgb(255, 99, 132)',
                tension: 0.1
            }
        ]
    };

    return (
        <div className={styles.profilePage}>
            <h1 className={styles.pageTitle}>Welcome {editedData.username}!</h1>
            <div className={styles.cardContainer}>
                <div className={styles.profileDataCard}>
                    <h2 className={styles.cardTitle}>Profile Information</h2>
                    <form onSubmit={handleSubmit}>
                        <div className={styles.formGroup}>
                            <label htmlFor="name">Name:</label>
                            <input
                                type="text"
                                id="name"
                                name="name"
                                value={editedData.name}
                                onChange={handleInputChange}
                            />
                        </div>
                        <div className={styles.formGroup}>
                            <label htmlFor="surname">Surname:</label>
                            <input
                                type="text"
                                id="surname"
                                name="surname"
                                value={editedData.surname}
                                onChange={handleInputChange}
                            />
                        </div>
                        <div className={styles.formGroup}>
                            <label htmlFor="email">Email:</label>
                            <input
                                type="email"
                                id="email"
                                name="email"
                                value={editedData.email}
                                onChange={handleInputChange}
                            />
                            {validationErrors.email && <span className={styles.error}>{validationErrors.email}</span>}
                        </div>
                        <button type="submit" className={styles.submitButton}>Update Profile</button>
                        <button type="button" className={styles.passwordButton} onClick={() => setIsPasswordModalOpen(true)}>Change Password</button>
                    </form>
                </div>
                <div className={styles.statsCard}>
                    <h2 className={styles.cardTitle}>Game Statistics</h2>
                    <div className={styles.statsContainer}>
                        <div className={styles.statItem}>
                            <span className={styles.statLabel}>Total Games:</span>
                            <span className={styles.statValue}>{userData.games || 0}</span>
                        </div>
                        <div className={styles.statItem}>
                            <span className={styles.statLabel}>Wins:</span>
                            <span className={styles.statValue}>{userData.wins || 0}</span>
                        </div>
                        <div className={styles.statItem}>
                            <span className={styles.statLabel}>Losses:</span>
                            <span className={styles.statValue}>{userData.loses || 0}</span>
                        </div>
                        <div className={styles.statItem}>
                            <span className={styles.statLabel}>Win Ratio:</span>
                            <span className={styles.statValue}>
                                {userData.winRatio ? userData.winRatio.toFixed(2) : '0.00'}
                            </span>
                        </div>
                    </div>
                    <div className={styles.chartContainer}>
                        {userData.gameHistory && userData.gameHistory.length > 0 ? (
                            <Line data={chartData} options={{ responsive: true, maintainAspectRatio: false }} />
                        ) : (
                            <p className={styles.noDataMessage}>No game history available</p>
                        )}
                    </div>
                </div>
            </div>
            <PasswordChangeModal 
                isOpen={isPasswordModalOpen} 
                onClose={() => setIsPasswordModalOpen(false)}
                userId={userId}
                axiosAuth={axiosAuth}
            />
        </div>
    );
};

export default ProfilePage;
